def build():
    import json, os, re
    here = os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "ui", "locales")
    seen = {}
    for row in T:
        assert len(row) == 1 + len(LANGS), row
        ru = row[0]
        assert ru not in seen, "дубликат: " + ru
        seen[ru] = True
        ph = sorted(re.findall(r"\{\d+\}", ru))
        for lang, tr in zip(LANGS, row[1:]):
            assert sorted(re.findall(r"\{\d+\}", tr)) == ph, (lang, ru, tr)
    for i, lang in enumerate(LANGS):
        d = {row[0]: row[i + 1] for row in T}
        body = json.dumps(d, ensure_ascii=False, indent=1)
        js = ("// Сгенерировано из scripts/translations.py — правьте там.\n"
              "// SPDX-License-Identifier: GPL-3.0-or-later\n"
              f"(window.LINFIX_LOCALES = window.LINFIX_LOCALES || {{}}).{lang} = {body};\n")
        open(os.path.join(here, f"{lang}.js"), "w", encoding="utf-8", newline="\n").write(js)
    print(len(T), "строк ×", len(LANGS), "языков")


if __name__ == "__main__":
    build()
